# usage: mk.py <outdir> <kind>   creates archives from a fixed source tree
import os, sys, zipfile
import fsutil
out = sys.argv[1]
os.makedirs(out, exist_ok=True)
src = os.path.join(out, "src")
fsutil.create_file(os.path.join(src,"f1.txt"), content="one")
fsutil.create_file(os.path.join(src,"sub/f2.txt"), content="two")
fsutil.create_file(os.path.join(src,"sub/deep/f3.txt"), content="three")
fsutil.make_dirs(os.path.join(src,"emptydir"))
print("impl:", fsutil.__file__)
try:
    fsutil.create_tar_file(os.path.join(out,"a.tar"), [src], compression="")
    print("tar plain: ok")
except Exception as e: print("tar plain FAIL", type(e).__name__, e)
for name,val in [("gz","gz"),("bz2","bz2"),("xz","xz")]:
    try:
        fsutil.create_tar_file(os.path.join(out,f"a.tar.{name}"), [src], compression=val)
        print(f"tar {name}: ok")
    except Exception as e: print(f"tar {name} FAIL", type(e).__name__, e)
for name,val in [("stored",zipfile.ZIP_STORED),("deflated",zipfile.ZIP_DEFLATED),("bzip2",zipfile.ZIP_BZIP2),("lzma",zipfile.ZIP_LZMA)]:
    try:
        fsutil.create_zip_file(os.path.join(out,f"a_{name}.zip"), [src], compression=val)
        print(f"zip {name}: ok")
    except Exception as e: print(f"zip {name} FAIL", type(e).__name__, e)
