# usage: ex.py <archdir> <destroot>
import os, sys
import fsutil
ad, dr = sys.argv[1], sys.argv[2]
print("impl:", fsutil.__file__)
def tree(root):
    out={}
    for dp,dns,fns in os.walk(root):
        rel=os.path.relpath(dp,root)
        for fn in fns: out[os.path.normpath(os.path.join(rel,fn))]=open(os.path.join(dp,fn)).read()
        if not fns and not dns: out[os.path.normpath(rel)+"/"]="<empty>"
    return dict(sorted(out.items()))
for f in sorted(os.listdir(ad)):
    fp=os.path.join(ad,f)
    if not os.path.isfile(fp): continue
    dest=os.path.join(dr,f.replace(".","_"))
    try:
        if ".tar" in f: fsutil.extract_tar_file(fp, dest)
        elif f.endswith(".zip"): fsutil.extract_zip_file(fp, dest)
        else: continue
        print(f"{f}: OK {tree(dest)}")
    except Exception as e:
        print(f"{f}: FAIL {type(e).__name__}: {e}")
EOF
